// REPEAT-STOP for the index-time facts writer (RESULTS 61d). Port of findpics.facts_line (Python is the reference;
// golden parity test FactsLineTests on Tests/.../Fixtures/facts_line.json, regenerated by
// eval/facts_writer/facts_line_fixture.py).
//
// The writer emits one short line, "scene: ..; objects: a, b; colours: ..; people: ..". A small greedy model can loop
// ("objects: kilt, kilt, kilt, ..." up to the token cap). Decoding stops as soon as a COMPLETED list item (one followed
// by "," or ";") repeats an earlier completed item of the SAME field (fields = the ";"-separated "name: value" parts);
// the line is cut just before the repeated item (its leading "," dropped, then trailing " ,;" trimmed). Items compare
// lower-cased, whitespace runs collapsed, surrounding spaces and a trailing "." stripped. The decision depends only on
// the text generated so far, so checking each streamed prefix and stopping at the first hit gives exactly the cut of
// the full greedy output.
//
// App use (MAC_INBOX): in the facts writer's generate loop, after each chunk call `FactsLine.shouldStop(text)`; when
// true, stop generating and store `FactsLine.applyRepeatStop(text).line`.
import Foundation

public enum FactsLine {
    /// Offsets are in Unicode scalars (= Python str indices).
    public struct Scan: Equatable { public let cut: Int; public let end: Int }

    private static func isSpace(_ u: Unicode.Scalar) -> Bool { u.properties.isWhitespace }

    private static func isASCIILetter(_ u: Unicode.Scalar) -> Bool {
        (u.value >= 65 && u.value <= 90) || (u.value >= 97 && u.value <= 122)
    }

    /// Python `_norm`: strip, lower, collapse whitespace runs to " ", strip, rstrip("."), strip.
    static func norm(_ s: [Unicode.Scalar]) -> String {
        let lowered = String(String.UnicodeScalarView(s)).lowercased()
        var out: [Unicode.Scalar] = []
        var pendingSpace = false
        for u in lowered.unicodeScalars {
            if isSpace(u) { pendingSpace = !out.isEmpty; continue }
            if pendingSpace { out.append(" "); pendingSpace = false }
            out.append(u)
        }
        while let l = out.last, l == "." { out.removeLast() }
        while let l = out.last, isSpace(l) { out.removeLast() }
        return String(String.UnicodeScalarView(out))
    }

    /// Python `_FIELD = \s*[A-Za-z][A-Za-z ]*:\s*(.*)$` (re.S, match at start): "objects: kilt" -> "kilt".
    static func fieldValue(_ s: [Unicode.Scalar]) -> [Unicode.Scalar]? {
        var i = 0
        while i < s.count, isSpace(s[i]) { i += 1 }
        guard i < s.count, isASCIILetter(s[i]) else { return nil }
        i += 1
        while i < s.count, isASCIILetter(s[i]) || s[i] == " " { i += 1 }
        guard i < s.count, s[i] == ":" else { return nil }
        i += 1
        while i < s.count, isSpace(s[i]) { i += 1 }
        return Array(s[i...])
    }

    /// Rule versions (findpics.facts_line.VERSIONS). v1 = the pre-registered rule: every ";" segment is a field, stop at
    /// the 2nd occurrence. v2: a new field starts only at a "name:" segment (the 2B's collapsed ";"-lists stay one
    /// field), stop at the 3rd occurrence (two equal items are often legitimate). RESULTS 61d decides which ships.
    public static let defaultVersion = 1

    /// (cut, end) or nil: `cut` = keep text[..<cut]; `end` = just past the "," / ";" that completed the repeated item.
    public static func repeatScan(_ text: String, version: Int = defaultVersion) -> Scan? {
        let named = version == 2, limit = version == 2 ? 3 : 2
        let t = Array(text.unicodeScalars)
        var seen: [String: Int] = [:]
        var itemStart = 0
        var firstInSeg = true
        for i in 0..<t.count {
            let ch = t[i]
            guard ch == "," || ch == ";" else { continue }
            var item = Array(t[itemStart..<i])
            if firstInSeg, let v = fieldValue(item) {
                item = v
                if named { seen.removeAll() }
            }
            let key = norm(item)
            if !key.isEmpty, (seen[key] ?? 0) + 1 >= limit {
                let cut = itemStart > 0 && (t[itemStart - 1] == "," || t[itemStart - 1] == ";") ? itemStart - 1 : itemStart
                return Scan(cut: cut, end: i + 1)
            }
            if !key.isEmpty { seen[key, default: 0] += 1 }
            itemStart = i + 1
            firstInSeg = ch == ";"
            if ch == ";" && !named { seen.removeAll() }
        }
        return nil
    }

    /// True as soon as the streamed text so far contains a completed repeated item: stop decoding.
    public static func shouldStop(_ generated: String, version: Int = defaultVersion) -> Bool {
        repeatScan(generated, version: version) != nil
    }

    /// (line after repeat-stop, stopped?)
    public static func applyRepeatStop(_ text: String, version: Int = defaultVersion) -> (line: String, stopped: Bool) {
        guard let s = repeatScan(text, version: version) else { return (text, false) }
        var kept = Array(text.unicodeScalars)[..<s.cut]
        while let l = kept.last, l == " " || l == "," || l == ";" { kept.removeLast() }
        return (String(String.UnicodeScalarView(kept)), true)
    }
}
